import unittest

from phone import normalize_phone


class NormalizePhoneTests(unittest.TestCase):
    def test_formats_ten_digit_number(self):
        self.assertEqual(normalize_phone("5551234567"), "(555) 123-4567")

    def test_strips_leading_country_code(self):
        self.assertEqual(normalize_phone("1-555-123-4567"), "(555) 123-4567")
        self.assertEqual(normalize_phone("15551234567"), "(555) 123-4567")

    def test_rejects_invalid_input(self):
        with self.assertRaises(ValueError):
            normalize_phone("12345")


if __name__ == "__main__":
    unittest.main()
